function calculateFactorial(n) {
  // Handle the base case for n = 0, where factorial is 1
  if (n === 0) {
    return 1;
  }

  // Handle negative input as per typical factorial definitions
  if (n < 0) {
    // Factorial is not defined for negative numbers, or can be considered an error
    throw new Error("Factorial is not defined for negative numbers.");
  }

  // Initialize the result variable
  let result = 1;

  // Loop from n down to 1 to compute the product
  for (let i = n; i > 0; i--) {
    // Multiply the current result by the current value of i
    result *= i;
  }

  // Return the calculated factorial
  return result; // The final computed factorial value
}

