const isPalindrome = (str) => {
  // Convert the string to lowercase to ignore case
  const lowerStr = str.toLowerCase();
  // Use a regular expression to remove non-alphanumeric characters
  const alphanumericStr = lowerStr.replace(/[^a-z0-9]/g, '');

  // Initialize two pointers
  let left = 0;
  let right = alphanumericStr.length - 1;

  // Loop while the left pointer is less than the right pointer
  while (left < right) {
    // If characters at current pointers do not match, it's not a palindrome
    if (alphanumericStr[left] !== alphanumericStr[right]) {
      return false; // Return false immediately
    }
    // Move the left pointer one step to the right
    left++;
    // Move the right pointer one step to the left
    right--;
  }

  // If the loop completes, the string is a palindrome
  return true; // All characters matched
};

