function findMax(arr) {
  if (arr.length === 0) { // Handle empty array case
    return undefined; // Or throw an error, depending on requirements
  }

  let max = arr[0]; // Initialize max with the first element of the array

  for (let i = 1; i < arr.length; i++) { // Loop through the rest of the array
    if (arr[i] > max) { // Compare current element with the current maximum
      max = arr[i]; // Update max if a larger element is found
    }
  }

  return max; // Return the largest number found
}

