function simpleCalculator(num1, operator, num2) {
  // Check if num1 and num2 are valid numbers
  if (typeof num1 !== 'number' || typeof num2 !== 'number') {
    return null; // Return null if inputs are not numbers
  }

  // Use a switch statement to handle different operators
  switch (operator) {
    case '+':
      return num1 + num2; // Perform addition
    case '-':
      return num1 - num2; // Perform subtraction
    case '*':
      return num1 * num2; // Perform multiplication
    case '/':
      // Handle division by zero case
      if (num2 === 0) {
        return null; // Return null for division by zero
      }
      return num1 / num2; // Perform division
    default:
      return null; // Return null for an invalid operator
  }
  // End of function execution
}

