const capitalizeFirstLetter = (str) => {
  // Split the input string into an array of words
  const words = str.split(' '); 

  // Map over each word to capitalize its first letter
  const capitalizedWords = words.map((word) => {
    // Handle empty strings or words to avoid errors
    if (word.length === 0) { 
      return '';
    }
    // Get the first character and convert it to uppercase
    const firstLetter = word.charAt(0).toUpperCase(); 
    // Get the rest of the word starting from the second character
    const restOfWord = word.slice(1); 
    // Combine the capitalized first letter with the rest of the word
    return firstLetter + restOfWord; 
  });

  // Join the array of capitalized words back into a single string
  return capitalizedWords.join(' '); 
};

// Example usage:
// console.log(capitalizeFirstLetter('hello world'));
// console.log(capitalizeFirstLetter('javascript is fun'));

