const swapKeysAndValues = (obj) => {
  const newObj = {}; // Initialize an empty object to store the swapped key-value pairs.

  // Iterate over each key in the input object.
  for (const key in obj) {
    // Check if the property belongs to the object itself (not its prototype chain).
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      const value = obj[key]; // Get the value associated with the current key.
      newObj[value] = key; // Assign the original key as the value to the original value as the new key.
    }
  }
  return newObj; // Return the new object with swapped keys and values.
};

