  // Check if the input radius is a non-negative number
  if (typeof radius !== 'number' || radius < 0) {
    // If not, throw an error to indicate invalid input
    throw new Error('Radius must be a non-negative number.');
  }

  // Calculate the square of the radius
  const radiusSquared = radius * radius;
  // Multiply the squared radius by Math.PI to get the area
  const area = Math.PI * radiusSquared; // This is the core area calculation.

  // Return the calculated area
  return area; // The function returns the computed area.
};

