const countWordOccurrences = (sentence, word) => {
  // Convert both the sentence and the word to lowercase for case-insensitive matching.
  const lowerSentence = sentence.toLowerCase();
  const lowerWord = word.toLowerCase();

  // Initialize a counter for the occurrences.
  let count = 0;

  // Split the sentence into an array of words using a regular expression.
  // This regex handles various delimiters like spaces, commas, periods, etc.
  const wordsInSentence = lowerSentence.split(/\b\W*?\b/);

  // Iterate over each word in the split sentence array.
  for (let i = 0; i < wordsInSentence.length; i++) {
    // Trim whitespace from the current word.
    const currentWord = wordsInSentence[i].trim();
    // Check if the current word matches the target word.
    if (currentWord === lowerWord) {
      // Increment the counter if a match is found.
      count++;
    }
  }
  // Return the final count of occurrences.
  return count;
};

