function calculateAge(birthdateStr) {
  const birthDate = new Date(birthdateStr); // Create a Date object from the birthdate string
  const today = new Date(); // Get the current date

  let age = today.getFullYear() - birthDate.getFullYear(); // Calculate the difference in years

  const monthDifference = today.getMonth() - birthDate.getMonth(); // Get month difference
  const dayDifference = today.getDate() - birthDate.getDate(); // Get day difference

  // If the birth month is after the current month, or
  // if the birth month is the same but the birth day is after the current day,
  // then the person hasn't had their birthday yet this year.
  if (monthDifference < 0 || (monthDifference === 0 && dayDifference < 0)) {
    age--; // Decrement age if birthday hasn't occurred yet this year
  }

  return age; // Return the calculated age
}

