const calculateHypotenuse = (a, b) => {
  // Calculate the square of side 'a'
  const aSquared = Math.pow(a, 2);
  // Calculate the square of side 'b'
  const bSquared = Math.pow(b, 2);

  // Sum the squares of the two sides
  const sumOfSquares = aSquared + bSquared;

  // Calculate the square root of the sum to find the hypotenuse
  const hypotenuse = Math.sqrt(sumOfSquares);

  // Return the calculated hypotenuse
  return hypotenuse;
};

