function sortNumbersAscending(arr) {
  // Check if the input is an array
  if (!Array.isArray(arr)) {
    throw new Error("Input must be an array."); // Throw an error for invalid input
  }

  // Create a shallow copy of the array to avoid modifying the original
  const newArr = [...arr];

  // Use the built-in sort method with a custom comparison function
  newArr.sort((a, b) => {
    // This comparison function sorts numbers in ascending order
    // If a is less than b, return a negative number (a comes before b)
    // If a is greater than b, return a positive number (a comes after b)
    // If a is equal to b, return 0 (order doesn't matter)
    return a - b; // Standard ascending sort for numbers
  });

  // Return the newly sorted array
  return newArr; // The function returns a new array, not the modified original
}

