function compressString(str) {
  let compressedString = ''; // Initialize an empty string to store the compressed result.
  let count = 0; // Initialize a counter for consecutive characters.

  for (let i = 0; i < str.length; i++) { // Iterate through the input string.
    count++; // Increment the count for the current character.

    // Check if it's the last character or the next character is different.
    if (i + 1 >= str.length || str[i] !== str[i + 1]) {
      compressedString += str[i] + count; // Append character and its count to compressedString.
      count = 0; // Reset the count for the next character sequence.
    }
  }

  // Compare the length of the compressed string with the original.
  if (compressedString.length < str.length) {
    return compressedString; // Return the compressed string if it's shorter.
  } else {
    return str; // Otherwise, return the original string.
  }
}

