function findSecondSmallest(arr) {
  let smallest = Infinity; // Initialize smallest to a very large number
  let secondSmallest = Infinity; // Initialize secondSmallest similarly

  // Iterate through each number in the input array
  for (let i = 0; i < arr.length; i++) {
    const num = arr[i]; // Get the current number

    // If the current number is smaller than the current smallest
    if (num < smallest) {
      secondSmallest = smallest; // The old smallest becomes the new second smallest
      smallest = num; // The current number becomes the new smallest
    } else if (num < secondSmallest && num !== smallest) {
      // If the current number is smaller than secondSmallest but not equal to smallest
      secondSmallest = num; // Update secondSmallest
    }
  }
  return secondSmallest; // Return the identified second smallest number
}

