function guessNumber(target, guess) {
  // Check if the guess is higher than the target number
  if (guess > target) {
    return 'Too high'; // Return "Too high" if the guess is too large
  } else if (guess < target) {
    // Check if the guess is lower than the target number
    return 'Too low'; // Return "Too low" if the guess is too small
  } else {
    // If neither 'Too high' nor 'Too low', the guess must be correct
    return 'Correct!'; // Return "Correct!" if the guess matches the target
  }
}

