function calculateBMI(weightKg, heightM) {
  // Ensure weight is a positive number
  if (weightKg <= 0 || typeof weightKg !== 'number') {
    throw new Error("Weight must be a positive number.");
  }
  // Ensure height is a positive number
  if (heightM <= 0 || typeof heightM !== 'number') {
    throw new Error("Height must be a positive number.");
  }

  const heightSquared = heightM * heightM; // Calculate the square of the height
  const bmi = weightKg / heightSquared;    // Perform the BMI calculation

  // Return the calculated BMI value
  return bmi;
}

